def retry_call(operation, attempts, wait, base=0.5):
    if attempts <= 0:
        raise ValueError("attempts must be positive")
    for attempt in range(attempts):
        try:
            return operation()
        except TimeoutError:
            if attempt == attempts-1:
                raise
            wait(base*(2**attempt))

