def resilient_map(texts, operation, attempts):
    if attempts <= 0:
        raise ValueError("attempts must be positive")
    cache={}
    result=[]
    for text in texts:
        if text not in cache:
            for attempt in range(attempts):
                try:
                    cache[text]=operation(text)
                    break
                except TimeoutError:
                    if attempt==attempts-1:
                        raise
        result.append(cache[text])
    return result

