def simulated_transport(payload):
    prompt=payload.get("prompt")
    limit=payload.get("max_words")
    if not isinstance(prompt,str) or not prompt.strip():
        raise ValueError("Invalid prompt")
    if type(limit) is not int or limit<=0:
        raise ValueError("Invalid max_words")
    words=prompt.split()[:limit]
    return {"text":" ".join(words),"usage":len(words),"simulated":True}

def send_with_retry(payload, transport, wait, attempts=3):
    if attempts<=0:
        raise ValueError("attempts must be positive")
    for index in range(attempts):
        try:
            return transport(payload)
        except TimeoutError:
            if index==attempts-1:
                raise
            wait(0.25*(2**index))

class AIClient:
    def __init__(self, transport, wait, events):
        self.transport=transport
        self.wait=wait
        self.events=events

    def generate(self, prompt, max_words=20):
        if not isinstance(prompt,str) or not prompt.strip() or type(max_words) is not int or max_words<=0:
            raise ValueError("Invalid request")
        payload={"prompt":prompt.strip(),"max_words":max_words}
        response=send_with_retry(payload,self.transport,self.wait)
        if not isinstance(response,dict) or not isinstance(response.get("text"),str) or type(response.get("usage")) is not int or response["usage"]<0 or type(response.get("simulated")) is not bool:
            raise ValueError("Invalid response")
        self.events.append({"event":"generation_complete","usage":response["usage"],"simulated":response["simulated"]})
        return response

